import sys

def is_word_char(c: str) -> bool:
    return c.isalnum()

def move_char_left(s, cur):
    return max(0, cur - 1)

def move_char_right(s, cur):
    return min(len(s), cur + 1)

def move_word_left(s, cur):
    i = cur
    # Skip non-word chars to the left
    while i > 0 and not is_word_char(s[i - 1]):
        i -= 1
    # Skip the word to the left
    while i > 0 and is_word_char(s[i - 1]):
        i -= 1
    return i

def move_word_right(s, cur):
    n = len(s)
    i = cur
    # Skip non-word chars to the right
    while i < n and not is_word_char(s[i]):
        i += 1
    # Skip the word to the right
    while i < n and is_word_char(s[i]):
        i += 1
    return i

def delete_char_left(s, cur):
    if cur == 0:
        return s, cur
    return s[:cur - 1] + s[cur:], cur - 1

def delete_char_right(s, cur):
    if cur == len(s):
        return s, cur
    return s[:cur] + s[cur + 1:], cur

def delete_word_left(s, cur):
    new_cur = move_word_left(s, cur)
    return s[:new_cur] + s[cur:], new_cur

def delete_word_right(s, cur):
    new_cur = move_word_right(s, cur)
    return s[:cur] + s[new_cur:], cur

def insert_text(s, cur, t):
    return s[:cur] + t + s[cur:], cur + len(t)

def solve():
    data = sys.stdin.read().splitlines()
    if not data:
        return

    # Expected format:
    # line 1: initial text
    # line 2: number of commands
    # next lines: commands
    text = data[0]
    if len(data) == 1:
        print(text)
        return

    try:
        n = int(data[1].strip())
        cmd_lines = data[2:2 + n]
    except:
        # Fallback: treat all remaining lines as commands
        cmd_lines = data[1:]

    s = text
    cur = len(s)  # usual editor convention

    for line in cmd_lines:
        line = line.rstrip('\n')

        if line == "forward character":
            cur = move_char_right(s, cur)
        elif line == "backward character":
            cur = move_char_left(s, cur)
        elif line == "forward word":
            cur = move_word_right(s, cur)
        elif line == "backward word":
            cur = move_word_left(s, cur)
        elif line == "delete character":
            s, cur = delete_char_right(s, cur)
        elif line == "delete word":
            s, cur = delete_word_right(s, cur)
        elif line == "backspace character":
            s, cur = delete_char_left(s, cur)
        elif line == "backspace word":
            s, cur = delete_word_left(s, cur)
        elif line.startswith("insert "):
            ins = line[7:]
            s, cur = insert_text(s, cur, ins)
        else:
            # Ignore unknown commands
            pass

    print(s)

