                    for (int j = 0; j < count && cursor < text.length(); j++) {
                        cursor++;
                    }
                }
            } else if (line.startsWith("BACKWARD")) {
                if (line.equals("BACKWARD")) {
                    if (cursor > 0) cursor--;
                } else {
                    int count = Integer.parseInt(line.split(" ")[1]);
                    for (int j = 0; j < count && cursor > 0; j++) {
                        cursor--;
                    }
                }
            } else if (line.startsWith("FORWARD_WORD")) {
                int count = 1;
                if (line.contains(" ")) {
                    count = Integer.parseInt(line.split(" ")[1]);
                }
                for (int w = 0; w < count && cursor < text.length(); w++) {
                    // skip non-word chars
                    while (cursor < text.length() && !isWordChar(text.charAt(cursor))) {
                        cursor++;
                    }
                    // skip word chars
                    while (cursor < text.length() && isWordChar(text.charAt(cursor))) {
                        cursor++;
                    }
                }
