                        cursor++;
                    }
                    // skip non-word chars to beginning of word
                    while (cursor > 0 && !isWordChar(text.charAt(cursor - 1))) {
                        cursor--;
                    }
                }
            } else if (line.startsWith("INSERT")) {
                String insertText = line.substring(7, line.length() - 1);
                text.insert(cursor, insertText);
                cursor += insertText.length();
            } else if (line.startsWith("DELETE")) {
                int count = 1;
                if (line.contains(" ")) {
                    count = Integer.parseInt(line.split(" ")[1]);
                }
                int end = Math.min(cursor + count, text.length());
                text.delete(cursor, end);
            } else if (line.startsWith("DELETE_WORD")) {
                int count = 1;
                if (line.contains(" ")) {
                    count = Integer.parseInt(line.split(" ")[1]);
                }
                for (int w = 0; w < count && cursor < text.length(); w++) {
                    // skip non-word chars
                    while (cursor < text.length() && !isWordChar(text.charAt(cursor))) {
                        text.deleteCharAt(cursor);
                    }
                    // skip word chars
                    while (cursor < text.length() && isWordChar(text.charAt(cursor))) {
                        text.deleteCharAt(cursor);
                    }
                }
            }
        }
        System.out.println(text.toString());
        sc.close();
    }

    private static boolean isWordChar(char c) {
        return Character.isLetterOrDigit(c) || c == '_';
    }
}

