import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        String nextLine() throws IOException {
            if (st != null && st.hasMoreTokens()) {
                StringBuilder sb = new StringBuilder(st.nextToken());
                while (st.hasMoreTokens()) sb.append(' ').append(st.nextToken());
                st = null;
                return sb.toString();
            }
            return br.readLine();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    static boolean isWordChar(char c) {
        return Character.isLetterOrDigit(c);
    }

    static int moveCharForward(StringBuilder sb, int cursor) {
        return Math.min(sb.length(), cursor + 1);
    }

    static int moveCharBackward(StringBuilder sb, int cursor) {
        return Math.max(0, cursor - 1);
    }

    static int moveWordForward(StringBuilder sb, int cursor) {
        int n = sb.length();
        int i = cursor;
        while (i < n && isWordChar(sb.charAt(i))) i++;
        while (i < n && !isWordChar(sb.charAt(i))) i++;
        return i;
    }

    static int moveWordBackward(StringBuilder sb, int cursor) {
        int i = cursor;
        while (i > 0 && !isWordChar(sb.charAt(i - 1))) i--;
        while (i > 0 && isWordChar(sb.charAt(i - 1))) i--;
        return i;
    }

    static int deleteCharForward(StringBuilder sb, int cursor) {
        if (cursor < sb.length()) sb.deleteCharAt(cursor);
        return cursor;
    }

    static int deleteCharBackward(StringBuilder sb, int cursor) {
        if (cursor > 0) {
            sb.deleteCharAt(cursor - 1);
            cursor--;
        }
        return cursor;
    }

    static int deleteWordForward(StringBuilder sb, int cursor) {
        int n = sb.length();
        int i = cursor;
        while (i < n && !isWordChar(sb.charAt(i))) i++;
        while (i < n && isWordChar(sb.charAt(i))) i++;
        if (i > cursor) sb.delete(cursor, i);
        return cursor;
    }

    static int deleteWordBackward(StringBuilder sb, int cursor) {
        int i = cursor;
        while (i > 0 && !isWordChar(sb.charAt(i - 1))) i--;
        while (i > 0 && isWordChar(sb.charAt(i - 1))) i--;
        if (i < cursor) {
            sb.delete(i, cursor);
            cursor = i;
        }
        return cursor;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        String text = br.readLine();
        if (text == null) return;

        String line = br.readLine();
        if (line == null) {
            System.out.print(text);
            return;
        }

        int q = Integer.parseInt(line.trim());
        StringBuilder sb = new StringBuilder(text);
        int cursor = 0;

        for (int cmdIdx = 0; cmdIdx < q; cmdIdx++) {
            String cmd = br.readLine();
            if (cmd == null) break;

            if (cmd.equals("forward character")) {
                cursor = moveCharForward(sb, cursor);
            } else if (cmd.equals("backward character")) {
                cursor = moveCharBackward(sb, cursor);
            } else if (cmd.equals("forward word")) {
                cursor = moveWordForward(sb, cursor);
            } else if (cmd.equals("backward word")) {
                cursor = moveWordBackward(sb, cursor);
            } else if (cmd.equals("delete character")) {
                cursor = deleteCharForward(sb, cursor);
            } else if (cmd.equals("delete previous character")) {
                cursor = deleteCharBackward(sb, cursor);
            } else if (cmd.equals("delete word")) {
                cursor = deleteWordForward(sb, cursor);
            } else if (cmd.equals("delete previous word")) {
                cursor = deleteWordBackward(sb, cursor);
            } else if (cmd.startsWith("insert ")) {
                String ins = cmd.substring(7);
                sb.insert(cursor, ins);
                cursor += ins.length();
            }
        }

        System.out.print(sb.toString());
    }
